[MenuItem("Anseong/Art/June Mountain Palette")]
public static void JuneMountainPalette(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/JuneMountains";Folder(folder);AssetDatabase.Refresh();var shader=AssetDatabase.LoadAssetAtPath<Shader>(folder+"/JuneForest.shader");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Forest shader invalid");var material=new Material(shader){name="JuneForest_Green",enableInstancing=true};var existing=AssetDatabase.LoadAssetAtPath<Material>(folder+"/JuneForest_Green.mat");if(existing){Object.DestroyImmediate(material);material=existing;material.shader=shader;}else AssetDatabase.CreateAsset(material,folder+"/JuneForest_Green.mat");material.SetColor("_NearGreen",new Color(.21f,.31f,.155f));material.SetColor("_FoothillGreen",new Color(.17f,.255f,.135f));material.SetColor("_SunGreen",new Color(.30f,.38f,.215f));material.SetColor("_DistantGreen",new Color(.30f,.36f,.31f));EditorUtility.SetDirty(material);var terrain=GameObject.Find("ConnectedCoastalHinterland");if(!terrain)throw new Exception("Missing connected hinterland");var renderer=terrain.GetComponent<MeshRenderer>();renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var slots=renderer.sharedMaterials;for(int i=0;i<slots.Length;i++)slots[i]=material;renderer.sharedMaterials=slots;File.WriteAllText(folder+"/README.md","# June mountain foliage\nConnected hinterland uses a texture-free four-colour foliage shader: dark foothills, mid green canopy, softly sunlit yellow-green patches, blue-green distance fade. Two world-space noise scales105m and22m blend colours without repeating texture tiles; height blend4–150m and distance haze2800–15500m. Existing mesh and material reused, zero added texture maps or trees. Canopy colours editable on JuneForest_Green.mat. Existing industrial paving, sand and water preserved. VR performance not measured.\n");AssetDatabase.SaveAssets();AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);ShaderUtil.allowAsyncCompilation=false;Shader.WarmupAllShaders();Capture(Camera.main,"JuneMountains_Main");var go=new GameObject("JuneMountainsPreview");var camera=go.AddComponent<Camera>();camera.CopyFrom(Camera.main);camera.transform.position=new Vector3(0,65,-120);camera.transform.rotation=Quaternion.Euler(-2,0,0);Capture(camera,"JuneMountains_RobotView");Object.DestroyImmediate(go);Debug.Log("JUNE_MOUNTAINS_PASS vegetationMaterial=true unchangedGeometry=true extraTrees=0 shaderErrors=0");}
